//---------------------------------------------------------------------------//
// Unit test for tools/sprintf
// Initial implementation generated by GitHub CoPilot (GPT-4.1)
//---------------------------------------------------------------------------//
#include "tools/sprintf"

#include <gtest/gtest.h>

namespace tools
{
//---------------------------------------------------------------------------//
TEST(Snpf, BasicFormatting)
{
  char buf[32];
  int n = snpf(buf, sizeof(buf), "Hello %s %d", "world", 42);
  EXPECT_GT(n, 0);
  EXPECT_STREQ(buf, "Hello world 42");
}

TEST(Snpf, BufferLimit)
{
  char buf[8];
  int n = snpf(buf, sizeof(buf), "abcdefghi");
  EXPECT_EQ(n, 9);
  EXPECT_EQ(buf[sizeof(buf) - 1], '\0');
  // Output should be truncated
  EXPECT_TRUE(std::string(buf).find("abcdefg") == 0);
}

TEST(Snpf, EmptyFormat)
{
  char buf[8];
  int n = snpf(buf, sizeof(buf), "");
  EXPECT_EQ(n, 0);
  EXPECT_STREQ(buf, "");
}

TEST(Snpf, ZeroBufferSize)
{
  char buf[1];
  int n = snpf(buf, 0, "test");
  EXPECT_EQ(n, 4);  // Nothing written
}

TEST(Snpf, IntegerFormatting)
{
  char buf[16];
  int n = snpf(buf, sizeof(buf), "%d", 12345);
  EXPECT_EQ(n, 5);
  EXPECT_STREQ(buf, "12345");
}

TEST(Snpf, FloatFormatting)
{
  char buf[32];
  int n = snpf(buf, sizeof(buf), "%.2f", 3.14159);
  EXPECT_EQ(n, 4);
  EXPECT_STREQ(buf, "3.14");
}

TEST(Snpf, MultipleArguments)
{
  char buf[32];
  int n = snpf(buf, sizeof(buf), "%s %d %.1f", "val", 7, 2.5);
  EXPECT_GT(n, 0);
  EXPECT_STREQ(buf, "val 7 2.5");
}

TEST(Snpf, ExponentFormattingTwoDigits)
{
  char buf[32];
  snpf(buf, sizeof(buf), "%.2e", 12.3);
  // Should be "1.23e+01" on modern platforms
  // Provided as a regression test as tools did support very old
  // MSVC versions with single digit exponents.
  EXPECT_STREQ(buf, "1.23e+01");
}

//---------------------------------------------------------------------------//
TEST(Sprintf, BasicFormatting)
{
  std::string s;
  EXPECT_TRUE(sprintf(s, 32, "Hello %s %d", "world", 42));
  EXPECT_EQ(s, "Hello world 42");
}

TEST(Sprintf, BufferLimit)
{
  std::string s;
  EXPECT_FALSE(sprintf(s, 5, "abcdef"));  // Needs 6 chars + null
  EXPECT_EQ(s, "");
}

TEST(Sprintf, EmptyFormat)
{
  std::string s;
  EXPECT_TRUE(sprintf(s, 8, ""));
  EXPECT_EQ(s, "");
}

TEST(Sprintf, NegativeLength)
{
  std::string s;
  EXPECT_FALSE(sprintf(s, -1, "test"));
  EXPECT_EQ(s, "");
}

TEST(Sprintf, NullFormat)
{
  std::string s;
  EXPECT_FALSE(sprintf(s, 8, nullptr));
  EXPECT_EQ(s, "");
}

TEST(Sprintf, IntegerFormatting)
{
  std::string s;
  EXPECT_TRUE(sprintf(s, 16, "%d", 12345));
  EXPECT_EQ(s, "12345");
}

TEST(Sprintf, FloatFormatting)
{
  std::string s;
  EXPECT_TRUE(sprintf(s, 16, "%.2f", 3.14159));
  EXPECT_EQ(s, "3.14");
}

TEST(Sprintf, MultipleArguments)
{
  std::string s;
  EXPECT_TRUE(sprintf(s, 32, "%s %d %.1f", "val", 7, 2.5));
  EXPECT_EQ(s, "val 7 2.5");
}

//---------------------------------------------------------------------------//
TEST(Vsprintf, BasicFormatting)
{
  std::string s;
  // Helper function to call vsprintf with va_list
  auto call_vsprintf = [](std::string& str, int len, const char* fmt, ...) {
    va_list args;
    va_start(args, fmt);
    bool result = vsprintf(str, len, fmt, args);
    va_end(args);
    return result;
  };
  EXPECT_TRUE(call_vsprintf(s, 32, "Hello %s %d", "world", 42));
  EXPECT_EQ(s, "Hello world 42");
}

//---------------------------------------------------------------------------//
}  // namespace tools
